SELECT
FROM order_info order_info
AND order_info.del_flag = '0'
AND order_info.shop_id = #{query.shopId}
and (order_info.order_no like '%' || #{query.keyword} || '%' or order_info.name like '%' || #{query.keyword} || '%')
AND order_info.user_id = #{query.userId}
AND order_info.order_type = #{query.orderType}
AND order_info.is_pay = '0' AND order_info.status is null
AND order_info.status = #{query.status}::text
AND order_info.order_no = #{query.orderNo}
ORDER BY
CASE WHEN order_info.status IS NULL AND order_info.is_pay = '0' THEN 0 WHEN order_info.status = '1' THEN 1 WHEN order_info.status = '2' THEN 2 WHEN order_info.status = '3' THEN 3 ELSE 4 END,
order_info.create_time DESC, order_info.id DESC

SELECT

FROM order_info order_info
WHERE order_info.id = #{id}
